  scene: { svg: `<svg viewBox="0 0 1200 640" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="640" fill="#fafafa"/><g transform="translate(160 440)"><g stroke="#ffffff" stroke-width="3"><g fill="#64b5f6"><rect x="0" y="-60" width="60" height="60"/><rect x="60" y="-60" width="60" height="60"/><rect x="120" y="-60" width="60" height="60"/><rect x="180" y="-60" width="60" height="60"/></g><g fill="#42a5f5"><animate attributeName="opacity" values="0;0;1;1" keyTimes="0;0.3;0.35;1" dur="9s" repeatCount="indefinite"/><rect x="0" y="-120" width="60" height="60"/><rect x="60" y="-120" width="60" height="60"/><rect x="120" y="-120" width="60" height="60"/><rect x="180" y="-120" width="60" height="60"/></g><g fill="#1e88e5"><animate attributeName="opacity" values="0;0;1;1" keyTimes="0;0.6;0.65;1" dur="9s" repeatCount="indefinite"/><rect x="0" y="-180" width="60" height="60"/><rect x="60" y="-180" width="60" height="60"/><rect x="120" y="-180" width="60" height="60"/><rect x="180" y="-180" width="60" height="60"/></g></g><path d="M0 -180l60 -50h240l-60 50zM240 0l60 -50v-180l-60 50z" fill="#bbdefb" stroke="#1565c0" stroke-width="3" opacity="0.6"/></g><g transform="translate(700 120)" fill="#ffe082" stroke="#f57f17" stroke-width="4"><rect x="120" y="0" width="120" height="120"/><rect x="0" y="120" width="120" height="120"/><rect x="120" y="120" width="120" height="120"><animate attributeName="fill" values="#ffe082;#ffb74d;#ffe082" dur="3s" repeatCount="indefinite"/></rect><rect x="240" y="120" width="120" height="120"/><rect x="360" y="120" width="120" height="120"/><rect x="120" y="240" width="120" height="120"/></g></svg>`,
   points: [{ t: 'Jednotkové kocky', d: 'Kváder 4 × 1 × 3 kociek: v každej vrstve sú 4 kocky, vrstvy sú 3. Objem je 12 kociek.', e: 'Spočítaj kocky.', ic: 'drop', x: 22, y: 62 }, { t: 'Vrstvy', d: 'Objem kvádra je počet kociek vo vrstve krát počet vrstiev.', e: 'Kocky sú vo vrstvách.', ic: 'castle', x: 30, y: 40 }, { t: 'Sieť kocky', d: 'Šesť zhodných štvorcov. Po zložení vznikne kocka. Povrch je súčet ich obsahov.', e: 'Toto je sieť kocky.', ic: 'map', x: 75, y: 38 }, { t: 'Dno a veko', d: 'Protiľahlé steny siete: po zložení budú oproti sebe.', e: 'Tieto steny budú oproti sebe.', ic: 'star', x: 68, y: 12, l: 2 }] },
  cards: [{ q: 'Koľko hrán má kváder?', a: '12.' }, { q: 'Ako vypočítame objem kvádra?', a: 'V = a · b · c.' }, { q: 'Ako vypočítame povrch kocky?', a: 'S = 6 · a · a.' }, { q: 'Koľko litrov je 1 dm³?', a: '1 liter.' }, { q: 'Vypočítaj objem a povrch kocky s hranou 3 cm.', a: 'V = 27 cm³, S = 54 cm².', l: 2 }, { q: 'Koľko dm³ je 1 m³?', a: '1 000 dm³.', l: 2 }],
  quiz: [{ q: 'Kváder má rozmery 2 cm, 3 cm a 4 cm. Aký je jeho objem?', o: ['24 cm³', '9 cm³', '52 cm³'], k: 0, w: '2 · 3 · 4 = 24 cm³.' }, { q: 'Aký je povrch toho istého kvádra?', o: ['52 cm²', '24 cm²', '26 cm²'], k: 0, w: '2 · (6 + 12 + 8) = 52 cm².' }, { q: 'V akých jednotkách meriame objem?', o: ['cm³', 'cm²', 'cm'], k: 0, w: 'Objem je v kubických jednotkách.' }, { q: 'Koľko litrov sa zmestí do akvária 50 cm × 30 cm × 40 cm?', o: ['60 l', '600 l', '6 l'], k: 0, w: '50 · 30 · 40 = 60 000 cm³ = 60 dm³ = 60 l.', l: 2 }],
